-- First start only (run by the image's migrate.sh as postgres): the database passwords of Auth and Storage.
-- Only SCRAM-SHA-256 verifiers are sent (generated by gen-secrets.sh): the image logs DDL statements, and
-- a verifier in a log line does not reveal the password. Changing a password later: run
-- `alter role supabase_auth_admin password '<new verifier>'` (or supabase_storage_admin) yourself and
-- update .secrets/.env.
\set verifier `echo "$AUTH_DB_PASSWORD_SCRAM"`
alter role supabase_auth_admin with login password :'verifier';
-- Supabase Storage (T-M2-18): its own login role, with its own password (never the superuser's).
\set storage_verifier `echo "$STORAGE_DB_PASSWORD_SCRAM"`
alter role supabase_storage_admin with login password :'storage_verifier';
